typedef float rational_t;

class stringx {};
stringx operator+(const stringx&, const char*);
stringx operator+(const stringx&, const stringx&);
void error(const stringx&);

class script_object {
public:
  class instance {
  public:
    const stringx& get_name() const;
  };
  const stringx& get_fullname() const;
};

class vm_thread {
public:
  script_object::instance* get_instance() const;
  script_object* get_executable() const;
};

class vm_stack {
public:
  int salloc;
  char* buffer;
  char* SP;
private:
  vm_thread* my_thread;
public:
  vm_thread* get_thread() const { return my_thread; }
  bool push(const char* src, int n);
};

class vector3d {
public:
  rational_t x, y, z;
  inline vector3d(rational_t _x, rational_t _y, rational_t _z)
  {
    x = _x; y = _y; z = _z;
  }
};

class color {
public:
  rational_t r, g, b, a;
  float get_red() const { return r; }
  float get_green() const { return g; }
  float get_blue() const { return b; }
};

template<class T>
class singleton_ptr {
  T* p;
public:
  operator T*() const { return p; }
};

class fog_manager {
  static singleton_ptr<fog_manager> instance;
public:
  static inline fog_manager* inst() { return instance; }
  color fog_color;
  color get_fog_color() const { return fog_color; }
};

class script_library_class {
public:
  class function {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    virtual bool operator()(vm_stack& stack, entry_t entry) { return true; }
  };
};

#define SLF_RETURN \
  if (!stack.push((char*)&result,sizeof(result)) ) \
    error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() )
#define SLF_DONE return true

class slf_get_fog_color_t : public script_library_class::function
{
  public:
    // library function execution
    virtual bool operator()(vm_stack& stack,entry_t entry)
    {
      vector3d result = vector3d( fog_manager::inst()->get_fog_color().get_red(),
                                fog_manager::inst()->get_fog_color().get_green(),
                                fog_manager::inst()->get_fog_color().get_blue() );
      SLF_RETURN;
      SLF_DONE;
    }
};
